WITH gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_burst FROM sessions), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT CASE WHEN island_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS island_id_tier, DATE_TRUNC('WEEK', started_at) AS week_start, APPROX_PERCENTILE(island_id, ARRAY(0.25, 0.5, 0.75)) AS island_id_quartiles, COUNT(*) AS cnt, SIZE(COLLECT_SET(device)) AS num_devices, MAX(started_at) AS ended_at, AVG(island_id) AS avg_island_id, PERCENT_RANK() OVER (PARTITION BY CASE WHEN island_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY SIZE(COLLECT_SET(device)) DESC) AS num_devices_percent_rank FROM islands GROUP BY CASE WHEN island_id >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('WEEK', started_at)
